/**
 * vtb_converter.js
 * Công cụ chuyển đổi file đầu vào Masterlist Vô tuyến mẫu cũ (37 cột)
 * sang mẫu mới chuẩn Masterlist 2027-2028 (sheet PL1.1 ML2027-2028)
 * 100% Client-side (Không cần server, bảo mật tuyệt đối)
 * Giữ nguyên 100% định dạng, font chữ, màu sắc, khung viền, định dạng số của phôi mẫu gốc
 * và tự động co gọn toàn bộ dòng trống thừa (Compact rows)
 */

// Phôi mẫu Masterlist 2027-2028_Mau_moi.xlsx chuẩn (Base64)
const VTB_NEW_TEMPLATE_B64 = "";

// Hàm decode Base64 sang Uint8Array / ArrayBuffer
function getVTBNewTemplateBuffer() {
  const binaryString = atob(VTB_NEW_TEMPLATE_B64);
  const len = binaryString.length;
  const bytes = new Uint8Array(len);
  for (let i = 0; i < len; i++) {
    bytes[i] = binaryString.charCodeAt(i);
  }
  return bytes.buffer;
}

async function loadVTBNewTemplateBuffer() {
  try {
    const response = await fetch('Masterlist%202027-2028_Mau_moi.xlsx', { cache: 'no-store' });
    if (!response.ok) throw new Error(`HTTP ${response.status}`);
    return await response.arrayBuffer();
  } catch (error) {
    console.warn('Không nạp được phôi Mẫu mới hiện hành, dùng bản nhúng dự phòng:', error);
    return getVTBNewTemplateBuffer();
  }
}

/**
 * Lấy đối tượng JSZip tương thích mọi môi trường (Browser & Node.js)
 */
function getJSZipInstance() {
  if (typeof window !== 'undefined' && window.JSZip) return window.JSZip;
  if (typeof JSZip !== 'undefined') return JSZip;
  if (typeof require !== 'undefined') {
    try { return require('./jszip.min.js'); } catch (e) {
      try { return require('jszip'); } catch (e2) {}
    }
  }
  throw new Error('Không tìm thấy thư viện JSZip để xử lý file Excel');
}

/**
 * Escape XML an toàn cho các chuỗi dữ liệu trong file xlsx
 */
function escapeXml(str) {
  if (!str) return '';
  return String(str)
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&apos;');
}

/**
 * Kiểm tra nhanh xem workbook có phải file mẫu cũ của VTB (37 cột) hay không
 */
function isOldVTBFormat(workbook) {
  if (!workbook || !workbook.SheetNames || workbook.SheetNames.length === 0) return false;
  const ws = workbook.Sheets[workbook.SheetNames[0]];
  if (!ws || !ws['!ref']) return false;

  const range = XLSX.utils.decode_range(ws['!ref']);
  if (range.e.c < 30) return false;

  let foundOldKeywords = 0;
  for (let r = 0; r <= Math.min(10, range.e.r); r++) {
    for (let c = 0; c <= Math.min(36, range.e.c); c++) {
      const cell = ws[XLSX.utils.encode_cell({ r: r, c: c })];
      if (cell && cell.v) {
        const str = String(cell.v).toUpperCase();
        if (str.includes('PHỤ LỤC: MASTER LIST CHI TIẾT') || str.includes('MASTER LIST CHI TIET')) foundOldKeywords += 2;
        if (str.includes('KHỐI LƯỢNG ĐẦU TƯ') || str.includes('KHOI LUONG DAU TU')) foundOldKeywords += 1;
        if (str.includes('GIÁ TRỊ ĐẦU TƯ') || str.includes('GIA TRI DAU TU')) foundOldKeywords += 1;
        if (str.includes('ĐẦU TƯ BẮT BUỘC') || str.includes('DAU TU BAT BUOC')) foundOldKeywords += 1;
        if (str.includes('UCTT') || str.includes('ƯCTT')) foundOldKeywords += 1;
        if (str.includes('VÙNG PHỦ') || str.includes('VUNG PHU')) foundOldKeywords += 1;
        if (str.includes('DUNG LƯỢNG') || str.includes('DUNG LUONG')) foundOldKeywords += 1;
      }
    }
  }

  return foundOldKeywords >= 3;
}

/**
 * Phân tích và trích xuất dữ liệu từ file mẫu cũ VTB (37 cột)
 */
function parseOldVTBWorkbook(workbook) {
  const ws = workbook.Sheets[workbook.SheetNames[0]];
  const range = XLSX.utils.decode_range(ws['!ref']);

  const items = [];
  let currentVendor = '';
  let totalOld27 = 0;
  let totalOld28 = 0;

  for (let r = 8; r <= range.e.r; r++) {
    const cellA = ws[XLSX.utils.encode_cell({ r: r, c: 0 })];
    const cellB = ws[XLSX.utils.encode_cell({ r: r, c: 1 })];
    const cellC = ws[XLSX.utils.encode_cell({ r: r, c: 2 })];

    const tt = cellA && cellA.v !== undefined ? String(cellA.v).trim() : '';
    const name = cellB && cellB.v !== undefined ? String(cellB.v).trim() : '';
    const dvt = cellC && cellC.v !== undefined ? String(cellC.v).trim() : '';

    if (!name && !tt) continue;

    const nameUpper = name.toUpperCase();
    if (nameUpper.includes('TỔNG ĐẦU TƯ') || nameUpper.includes('VÔ TUYẾN')) {
      const cellAB = ws[XLSX.utils.encode_cell({ r: r, c: 27 })];
      const cellAJ = ws[XLSX.utils.encode_cell({ r: r, c: 35 })];
      if (cellAB && typeof cellAB.v === 'number') totalOld27 = cellAB.v;
      if (cellAJ && typeof cellAJ.v === 'number') totalOld28 = cellAJ.v;
    }

    if (['2.1', '2.2', '2.3', '5'].includes(tt) || nameUpper === 'HUAWEI' || nameUpper === 'ZTE' || nameUpper === 'ANTENA' || nameUpper.includes('CỦNG CỐ MẠNG LƯỚI')) {
      currentVendor = name;
      continue;
    }

    const cellT = ws[XLSX.utils.encode_cell({ r: r, c: 19 })];
    const dg = cellT && typeof cellT.v === 'number' ? cellT.v : (cellT && !isNaN(Number(cellT.v)) ? Number(cellT.v) : null);
    if (!dg) continue;

    const getNum = (cIdx) => {
      const cell = ws[XLSX.utils.encode_cell({ r: r, c: cIdx })];
      if (!cell || cell.v === undefined || cell.v === null || cell.v === '') return 0;
      const n = Number(cell.v);
      return isNaN(n) ? 0 : n;
    };

    const kl_uctt_27 = getNum(3);
    const kl_bbk_27  = getNum(4);
    const kl_vp_27   = getNum(5);
    const kl_gn_27   = getNum(6);
    const kl_tt_27   = getNum(7);
    const kl_cg_27   = getNum(8);
    const kl_hd_27   = getNum(9);
    const kl_tong_27 = getNum(10);

    const kl_uctt_28 = getNum(11);
    const kl_bbk_28  = getNum(12);
    const kl_vp_28   = getNum(13);
    const kl_gn_28   = getNum(14);
    const kl_tt_28   = getNum(15);
    const kl_cg_28   = getNum(16);
    const kl_hd_28   = getNum(17);
    const kl_tong_28 = getNum(18);

    const cellAB = ws[XLSX.utils.encode_cell({ r: r, c: 27 })];
    const cellAJ = ws[XLSX.utils.encode_cell({ r: r, c: 35 })];
    const tt27 = cellAB && typeof cellAB.v === 'number' ? cellAB.v : (dg ? kl_tong_27 * dg : 0);
    const tt28 = cellAJ && typeof cellAJ.v === 'number' ? cellAJ.v : (dg ? kl_tong_28 * dg : 0);

    items.push({
      row: r + 1,
      tt: tt,
      vendor: currentVendor,
      name: name,
      dvt: dvt,
      dg: dg,
      kl_uctt_27: kl_uctt_27,
      kl_bbk_27: kl_bbk_27,
      kl_vp_27: kl_vp_27,
      kl_gn_27: kl_gn_27,
      kl_tt_27: kl_tt_27,
      kl_cg_27: kl_cg_27,
      kl_hd_27: kl_hd_27,
      kl_tong_27: kl_tong_27,
      kl_uctt_28: kl_uctt_28,
      kl_bbk_28: kl_bbk_28,
      kl_vp_28: kl_vp_28,
      kl_gn_28: kl_gn_28,
      kl_tt_28: kl_tt_28,
      kl_cg_28: kl_cg_28,
      kl_hd_28: kl_hd_28,
      kl_tong_28: kl_tong_28,
      tt27: tt27,
      tt28: tt28
    });
  }

  let sumCalculated27 = 0;
  let sumCalculated28 = 0;
  items.forEach(it => {
    sumCalculated27 += it.tt27;
    sumCalculated28 += it.tt28;
  });
  if (!totalOld27 || Math.abs(totalOld27 - sumCalculated27) > 1) totalOld27 = sumCalculated27;
  if (!totalOld28 || Math.abs(totalOld28 - sumCalculated28) > 1) totalOld28 = sumCalculated28;

  return {
    items: items,
    totalOld27: totalOld27,
    totalOld28: totalOld28
  };
}

/**
 * Chuẩn hóa chuỗi để so sánh
 */
function normalizeItemName(str) {
  if (!str) return '';
  return str
    .toLowerCase()
    .replace(/^huawei_/i, '')
    .replace(/^zte_/i, '')
    .replace(/[\r\n]+/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}

const VTB_TECHNOLOGIES = ['5G', '4G', '3G', '2G'];

function suggestVTBTechnology(name) {
  const normalized = normalizeItemName(name).toUpperCase();
  return VTB_TECHNOLOGIES.find(technology => normalized.includes(technology)) || '';
}

function buildVTBMappingRows(items) {
  return items
    .filter(item => (item.kl_vp_27 || 0) > 0 || (item.kl_vp_28 || 0) > 0 ||
      (item.kl_tt_27 || 0) > 0 || (item.kl_tt_28 || 0) > 0)
    .map(item => ({
      id: String(item.row),
      row: item.row,
      vendor: item.vendor,
      name: item.name,
      coverage27: item.kl_vp_27 || 0,
      coverage28: item.kl_vp_28 || 0,
      capacity27: item.kl_tt_27 || 0,
      capacity28: item.kl_tt_28 || 0,
      suggestion: suggestVTBTechnology(item.name)
    }));
}

function applyVTBBulkTechnology(assignments, selectedIds, technology) {
  if (!VTB_TECHNOLOGIES.includes(technology)) return { ...(assignments || {}) };
  const updated = { ...(assignments || {}) };
  (selectedIds || []).forEach(id => {
    updated[String(id)] = technology;
  });
  return updated;
}

function splitOldVTBItems(items, assignments) {
  const rows = [];
  const missingAssignments = [];
  const unmappedAmounts = [];
  const normalizedAssignments = assignments || {};

  function addRow(item, purpose, branch, maDV, kl27, kl28) {
    if (!(kl27 > 0) && !(kl28 > 0)) return;
    rows.push({
      sourceRow: item.row,
      oldName: item.name,
      oldVendor: item.vendor,
      name: item.name,
      dvt: item.dvt,
      dg: item.dg,
      purpose,
      branch,
      maMang: 'VT',
      maDV,
      maLoai: 'VTTB',
      kl27: kl27 || 0,
      kl28: kl28 || 0,
      tt27: (kl27 || 0) * item.dg,
      tt28: (kl28 || 0) * item.dg
    });
  }

  items.forEach(item => {
    addRow(
      item,
      'UCTT + Đầu tư bắt buộc khác',
      'quality',
      'ƯCTT',
      (item.kl_uctt_27 || 0) + (item.kl_bbk_27 || 0),
      (item.kl_uctt_28 || 0) + (item.kl_bbk_28 || 0)
    );

    const hasManualPurpose = (item.kl_vp_27 || 0) > 0 || (item.kl_vp_28 || 0) > 0 ||
      (item.kl_tt_27 || 0) > 0 || (item.kl_tt_28 || 0) > 0;
    const technology = normalizedAssignments[String(item.row)] || '';
    if (hasManualPurpose && !VTB_TECHNOLOGIES.includes(technology)) {
      missingAssignments.push(String(item.row));
    } else if (hasManualPurpose) {
      const is5G = technology === '5G';
      const suffix = technology.toLowerCase();
      addRow(
        item,
        'Vùng phủ',
        is5G ? 'network_5g' : `coverage_${suffix}`,
        is5G ? '5G' : 'VPDĐ',
        item.kl_vp_27 || 0,
        item.kl_vp_28 || 0
      );
      addRow(
        item,
        'Tăng trưởng lưu lượng',
        is5G ? 'network_5g' : `capacity_${suffix}`,
        is5G ? '5G' : 'DLDĐ',
        item.kl_tt_27 || 0,
        item.kl_tt_28 || 0
      );
    }

    addRow(
      item,
      'Hiện đại hóa, thông minh hóa',
      'modernization',
      'VHKT',
      item.kl_hd_27 || 0,
      item.kl_hd_28 || 0
    );

    [
      ['Giải nghẽn, nâng cấp', 2027, item.kl_gn_27 || 0],
      ['Giải nghẽn, nâng cấp', 2028, item.kl_gn_28 || 0],
      ['Củng cố bền vững', 2027, item.kl_cg_27 || 0],
      ['Củng cố bền vững', 2028, item.kl_cg_28 || 0]
    ].forEach(([column, year, quantity]) => {
      if (quantity > 0) unmappedAmounts.push({ row: item.row, column, year, quantity });
    });
  });

  return { rows, missingAssignments, unmappedAmounts };
}

/**
 * Đánh lại số dòng và công thức SUBTOTAL cho một dòng tiêu đề phôi mẫu
 */
function renumberHeaderRow(origXml, newRowNum, subtotalStart, subtotalEnd) {
  const cellRe = /<c\b[^>]*?(?:\/>|>.*?<\/c>)/gs;
  const newCells = [];
  let m;
  while ((m = cellRe.exec(origXml)) !== null) {
    const fullCell = m[0];
    const colMatch = fullCell.match(/r="([A-Z]+)\d+"/);
    if (!colMatch) continue;
    const col = colMatch[1];
    const sMatch = fullCell.match(/s="(\d+)"/);
    const sAttr = sMatch ? ` s="${sMatch[1]}"` : '';
    
    if (col === 'G' || col === 'H') {
      if (subtotalStart !== null && subtotalEnd !== null && subtotalStart <= subtotalEnd) {
        newCells.push(`<c r="${col}${newRowNum}"${sAttr}><f>SUBTOTAL(9,${col}${subtotalStart}:${col}${subtotalEnd})</f><v>0</v></c>`);
      } else {
        newCells.push(`<c r="${col}${newRowNum}"${sAttr}><v>0</v></c>`);
      }
    } else {
      const renumbered = fullCell.replace(/r="[A-Z]+\d+"/, `r="${col}${newRowNum}"`);
      newCells.push(renumbered);
    }
  }
  
  const rowOpenMatch = origXml.match(/<row\b[^>]*?>/);
  const rowOpen = rowOpenMatch[0].replace(/r="\d+"/, `r="${newRowNum}"`);
  return `${rowOpen}${newCells.join('')}</row>`;
}

/**
 * Tạo một dòng dữ liệu vật tư với đầy đủ style, border, format số từ phôi mẫu gốc
 */
function createVTBItemRow(rNum, item, outlineLevel = 4) {
  const sTT = '77';      // Căn giữa, có khung viền
  const sName = '63';    // Căn trái, wrap text, có khung viền
  const sDVT = '74';     // Căn giữa, có khung viền
  const sKL = '81';      // Căn giữa/phải, format số _(* #,##0_), có khung viền
  const sDG_TT = '75';   // Căn phải, format số _(* #,##0_), có khung viền
  const sDVTH = '76';    // Căn giữa, có khung viền
  const sMa = '38';      // Căn giữa (Mã mảng, Mã DV, Mã loại)

  const cellA = `<c r="A${rNum}" s="${sTT}" t="inlineStr"><is><t>-</t></is></c>`;
  const cellB = `<c r="B${rNum}" s="${sName}" t="inlineStr"><is><t>${escapeXml(item.name)}</t></is></c>`;
  const cellC = item.dvt ? `<c r="C${rNum}" s="${sDVT}" t="inlineStr"><is><t>${escapeXml(item.dvt)}</t></is></c>` : `<c r="C${rNum}" s="${sDVT}"/>`;
  const cellD = item.kl27 > 0 ? `<c r="D${rNum}" s="${sKL}"><v>${item.kl27}</v></c>` : `<c r="D${rNum}" s="${sKL}"/>`;
  const cellE = item.kl28 > 0 ? `<c r="E${rNum}" s="${sKL}"><v>${item.kl28}</v></c>` : `<c r="E${rNum}" s="${sKL}"/>`;
  const cellF = item.dg ? `<c r="F${rNum}" s="${sDG_TT}"><v>${item.dg}</v></c>` : `<c r="F${rNum}" s="${sDG_TT}"/>`;
  const cellG = item.kl27 > 0 ? `<c r="G${rNum}" s="${sDG_TT}"><f>F${rNum}*D${rNum}</f><v>${item.tt27}</v></c>` : `<c r="G${rNum}" s="${sDG_TT}"/>`;
  const cellH = item.kl28 > 0 ? `<c r="H${rNum}" s="${sDG_TT}"><f>F${rNum}*E${rNum}</f><v>${item.tt28}</v></c>` : `<c r="H${rNum}" s="${sDG_TT}"/>`;
  const cellI = `<c r="I${rNum}" s="${sDVTH}"/>`;
  const cellJ = item.maMang ? `<c r="J${rNum}" s="${sMa}" t="inlineStr"><is><t>${escapeXml(item.maMang)}</t></is></c>` : `<c r="J${rNum}" s="${sMa}"/>`;
  const cellK = item.maDV ? `<c r="K${rNum}" s="${sMa}" t="inlineStr"><is><t>${escapeXml(item.maDV)}</t></is></c>` : `<c r="K${rNum}" s="${sMa}"/>`;
  const cellL = item.maLoai ? `<c r="L${rNum}" s="${sMa}" t="inlineStr"><is><t>${escapeXml(item.maLoai)}</t></is></c>` : `<c r="L${rNum}" s="${sMa}"/>`;

  return `<row r="${rNum}" spans="1:12" s="48" customFormat="1" ht="27.95" customHeight="1" outlineLevel="${outlineLevel}" x14ac:dyDescent="0.25">${cellA}${cellB}${cellC}${cellD}${cellE}${cellF}${cellG}${cellH}${cellI}${cellJ}${cellK}${cellL}</row>`;
}

/**
 * Thực hiện chuyển đổi từ file cũ sang file mới
 * Bảo toàn 100% styles.xml phôi mẫu gốc bằng JSZip
 * Tự động xóa gọn dòng trống thừa (Compact rows) và tính toán lại toàn bộ dải công thức SUBTOTAL
 */
async function convertOldVTBToNewFormat(oldWorkbook, assignments = {}, templateOverride = null) {
  const oldData = parseOldVTBWorkbook(oldWorkbook);
  const splitResult = splitOldVTBItems(oldData.items, assignments);
  if (splitResult.missingAssignments.length > 0) {
    const error = new Error(`Còn ${splitResult.missingAssignments.length} vật tư chưa được gán công nghệ.`);
    error.code = 'VTB_MAPPING_REQUIRED';
    error.rows = splitResult.missingAssignments;
    throw error;
  }
  if (splitResult.unmappedAmounts.length > 0) {
    const error = new Error('File có số lượng ở cột Giải nghẽn hoặc Củng cố chưa có quy tắc ánh xạ.');
    error.code = 'VTB_UNMAPPED_SOURCE_COLUMNS';
    error.amounts = splitResult.unmappedAmounts;
    throw error;
  }

  const rowsByBranch = {
    network_5g: [],
    coverage_4g: [],
    coverage_3g: [],
    coverage_2g: [],
    capacity_4g: [],
    capacity_3g: [],
    capacity_2g: [],
    modernization: [],
    quality: [],
    contingency: []
  };

  splitResult.rows.forEach(row => {
    if (rowsByBranch[row.branch]) {
      rowsByBranch[row.branch].push(row);
    }
  });

  const templateBuffer = templateOverride || getVTBNewTemplateBuffer();
  const JSZipLib = getJSZipInstance();
  const zip = await JSZipLib.loadAsync(templateBuffer);
  let sheet1Xml = await zip.file('xl/worksheets/sheet1.xml').async('string');

  const rowRegex = /<row\s+[^>]*?r="(\d+)"[^>]*?>.*?<\/row>/gs;
  const templateRows = {};
  let m;
  while ((m = rowRegex.exec(sheet1Xml)) !== null) {
    templateRows[parseInt(m[1], 10)] = m[0];
  }

  // Dòng 1 đến 6 là tiêu đề bảng cố định
  const finalRows = [];
  for (let r = 1; r <= 6; r++) {
    if (templateRows[r]) finalRows.push(templateRows[r]);
  }

  let currentRow = 11;
  const mappedResults = [];

  function addBranchItems(branchId, outlineLevel = 4) {
    const items = rowsByBranch[branchId] || [];
    const start = items.length > 0 ? currentRow : null;
    const itemRows = [];
    items.forEach(item => {
      const rNum = currentRow++;
      itemRows.push(createVTBItemRow(rNum, item, outlineLevel));
      mappedResults.push({
        oldName: item.oldName,
        oldVendor: item.oldVendor,
        oldPurpose: item.purpose,
        targetRow: rNum,
        targetName: item.name,
        targetDV: item.maDV,
        technology: assignments[String(item.sourceRow)] || '',
        kl27: item.kl27,
        kl28: item.kl28,
        dg: item.dg,
        tt27: item.tt27,
        tt28: item.tt28
      });
    });
    const end = items.length > 0 ? currentRow - 1 : null;
    return { start, end, itemRows };
  }

  // Branch 1: network_5g (Template Row 11: A1 Mạng 5G)
  const row5GHeader = currentRow++;
  const { start: start5G, end: end5G, itemRows: itemRows5G } = addBranchItems('network_5g', 2);

  // Branch 2: A2 Mạng 2/3/4G (Template Row 22)
  const rowA2Header = currentRow++;
  const startA2 = currentRow;

  // Branch 2.1: I Vùng phủ (Template Row 23)
  const rowVPHeader = currentRow++;
  const startVP = currentRow;

  // Branch 2.1.1: 1 Thiết bị 4G (Template Row 24)
  const rowCov4GHeader = currentRow++;
  const { start: startCov4G, end: endCov4G, itemRows: itemRowsCov4G } = addBranchItems('coverage_4g', 4);

  // Branch 2.1.2: 2 Thiết bị 3G (Template Row 32)
  const rowCov3GHeader = currentRow++;
  const { start: startCov3G, end: endCov3G, itemRows: itemRowsCov3G } = addBranchItems('coverage_3g', 4);

  // Branch 2.1.3: 3 Thiết bị 2G (Template Row 39)
  const rowCov2GHeader = currentRow++;
  const { start: startCov2G, end: endCov2G, itemRows: itemRowsCov2G } = addBranchItems('coverage_2g', 4);
  const endVP = currentRow - 1;

  // Branch 2.2: II Dung lượng (Template Row 45)
  const rowDLHeader = currentRow++;
  const startDL = currentRow;

  // Branch 2.2.1: 1 Thiết bị 4G (Template Row 46)
  const rowCap4GHeader = currentRow++;
  const { start: startCap4G, end: endCap4G, itemRows: itemRowsCap4G } = addBranchItems('capacity_4g', 4);

  // Branch 2.2.2: 2 Thiết bị 3G (Template Row 52)
  const rowCap3GHeader = currentRow++;
  const { start: startCap3G, end: endCap3G, itemRows: itemRowsCap3G } = addBranchItems('capacity_3g', 4);

  // Branch 2.2.3: 3 Thiết bị 2G (Template Row 59)
  const rowCap2GHeader = currentRow++;
  const { start: startCap2G, end: endCap2G, itemRows: itemRowsCap2G } = addBranchItems('capacity_2g', 4);
  const endDL = currentRow - 1;

  // Branch 2.3: II Hiện đại hóa mạng lưới (Template Row 66)
  const rowHDHeader = currentRow++;
  const { start: startHD, end: endHD, itemRows: itemRowsHD } = addBranchItems('modernization', 2);

  // Branch 2.4: III Nâng cao chất lượng mạng (Template Row 69)
  const rowCLHeader = currentRow++;
  const { start: startCL, end: endCL, itemRows: itemRowsCL } = addBranchItems('quality', 2);
  const endA2 = currentRow - 1;

  // Branch 3: A3 Đảm bảo dự phòng ƯCTT (Template Row 81)
  const rowDPHeader = currentRow++;
  const { start: startDP, end: endDP, itemRows: itemRowsDP } = addBranchItems('contingency', 2);
  const lastRow = currentRow - 1;

  // Ráp các dòng Header chính với công thức SUBTOTAL đã điều chỉnh dải dòng
  finalRows.push(renumberHeaderRow(templateRows[7], 7, 8, lastRow));
  finalRows.push(renumberHeaderRow(templateRows[8], 8, 9, lastRow));
  finalRows.push(renumberHeaderRow(templateRows[9], 9, 10, lastRow));
  finalRows.push(renumberHeaderRow(templateRows[10], 10, 11, lastRow));

  // 5G
  finalRows.push(renumberHeaderRow(templateRows[11], row5GHeader, start5G, end5G));
  finalRows.push(...itemRows5G);

  // A2
  finalRows.push(renumberHeaderRow(templateRows[22], rowA2Header, startA2, endA2));

  // Vùng phủ
  finalRows.push(renumberHeaderRow(templateRows[23], rowVPHeader, startVP, endVP));
  finalRows.push(renumberHeaderRow(templateRows[24], rowCov4GHeader, startCov4G, endCov4G));
  finalRows.push(...itemRowsCov4G);
  finalRows.push(renumberHeaderRow(templateRows[32], rowCov3GHeader, startCov3G, endCov3G));
  finalRows.push(...itemRowsCov3G);
  finalRows.push(renumberHeaderRow(templateRows[39], rowCov2GHeader, startCov2G, endCov2G));
  finalRows.push(...itemRowsCov2G);

  // Dung lượng
  finalRows.push(renumberHeaderRow(templateRows[45], rowDLHeader, startDL, endDL));
  finalRows.push(renumberHeaderRow(templateRows[46], rowCap4GHeader, startCap4G, endCap4G));
  finalRows.push(...itemRowsCap4G);
  finalRows.push(renumberHeaderRow(templateRows[52], rowCap3GHeader, startCap3G, endCap3G));
  finalRows.push(...itemRowsCap3G);
  finalRows.push(renumberHeaderRow(templateRows[59], rowCap2GHeader, startCap2G, endCap2G));
  finalRows.push(...itemRowsCap2G);

  // Hiện đại hóa
  finalRows.push(renumberHeaderRow(templateRows[66], rowHDHeader, startHD, endHD));
  finalRows.push(...itemRowsHD);

  // Nâng cao chất lượng
  finalRows.push(renumberHeaderRow(templateRows[69], rowCLHeader, startCL, endCL));
  finalRows.push(...itemRowsCL);

  // Dự phòng ƯCTT
  finalRows.push(renumberHeaderRow(templateRows[81], rowDPHeader, startDP, endDP));
  finalRows.push(...itemRowsDP);

  // Thay thế sheetData trong sheet1.xml
  const newSheetDataXml = `<sheetData>${finalRows.join('')}</sheetData>`;
  sheet1Xml = sheet1Xml.replace(/<sheetData>.*?<\/sheetData>/s, newSheetDataXml);

  // Cập nhật dimension và autofilter
  sheet1Xml = sheet1Xml.replace(/<dimension ref="[^"]*"/, `<dimension ref="A1:Q${lastRow}"`);
  sheet1Xml = sheet1Xml.replace(/<autoFilter ref="[^"]*"/, `<autoFilter ref="A7:Q${lastRow}"`);

  zip.file('xl/worksheets/sheet1.xml', sheet1Xml);

  // Cấu hình workbook tự động tính toán lại công thức khi mở trong Excel
  let wbXml = await zip.file('xl/workbook.xml').async('string');
  if (!wbXml.includes('calcPr')) {
    wbXml = wbXml.replace('</workbook>', '<calcPr fullCalcOnLoad="1" forceFullCalc="1"/></workbook>');
  } else {
    wbXml = wbXml.replace(/<calcPr([^>]*?)\/>/, '<calcPr$1 fullCalcOnLoad="1" forceFullCalc="1"/>');
  }
  zip.file('xl/workbook.xml', wbXml);

  // Xóa calcChain.xml cũ để Excel tự động lập lại cây tính toán mới
  zip.remove('xl/calcChain.xml');
  const ctFile = zip.file('[Content_Types].xml');
  if (ctFile) {
    let contentTypes = await ctFile.async('string');
    contentTypes = contentTypes.replace(/<Override[^>]*PartName="\/xl\/calcChain\.xml"[^>]*\/>/, '');
    zip.file('[Content_Types].xml', contentTypes);
  }
  const relsFile = zip.file('xl/_rels/workbook.xml.rels');
  if (relsFile) {
    let wbRels = await relsFile.async('string');
    wbRels = wbRels.replace(/<Relationship[^>]*Target="calcChain\.xml"[^>]*\/>/, '');
    zip.file('xl/_rels/workbook.xml.rels', wbRels);
  }

  // Đóng gói ArrayBuffer nguyên vẹn 100% styles.xml
  const convertedBuffer = await zip.generateAsync({ type: 'arraybuffer', compression: 'DEFLATE' });
  const convertedWorkbook = XLSX.read(convertedBuffer, { type: 'array', cellFormula: true });

  const newTotal27 = mappedResults.reduce((sum, item) => sum + (item.tt27 || 0), 0);
  const newTotal28 = mappedResults.reduce((sum, item) => sum + (item.tt28 || 0), 0);

  return {
    convertedWorkbook,
    convertedBuffer,
    totalOld27: oldData.totalOld27,
    totalOld28: oldData.totalOld28,
    newTotal27,
    newTotal28,
    mappedResults,
    oldItemsCount: oldData.items.length,
    mappedCount: mappedResults.length
  };
}

// Xuất các hàm ra phạm vi toàn cục window
window.VTBConverter = {
  isOldVTBFormat: isOldVTBFormat,
  parseOldVTBWorkbook: parseOldVTBWorkbook,
  buildVTBMappingRows: buildVTBMappingRows,
  applyVTBBulkTechnology: applyVTBBulkTechnology,
  splitOldVTBItems: splitOldVTBItems,
  convertOldVTBToNewFormat: convertOldVTBToNewFormat,
  getVTBNewTemplateBuffer: getVTBNewTemplateBuffer,
  loadVTBNewTemplateBuffer: loadVTBNewTemplateBuffer
};
